import{_ as a,o as e,c as d,a3 as o}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"模型应用基础","description":"从消息与 Prompt 输入开始，建立模型请求、结构化结果、业务校验、流式处理、可靠性和基础评测的完整应用边界。","frontmatter":{"title":"模型应用基础","description":"从消息与 Prompt 输入开始，建立模型请求、结构化结果、业务校验、流式处理、可靠性和基础评测的完整应用边界。","verified_at":"2026-07-29"},"headers":[],"relativePath":"py-agent/foundations/model-application/index.md","filePath":"py-agent/foundations/model-application/index.md","lastUpdated":1785291406000}'),i={name:"py-agent/foundations/model-application/index.md"};function n(r,t,l,p,s,c){return e(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="模型应用基础" tabindex="-1">模型应用基础 <a class="header-anchor" href="#模型应用基础" aria-label="Permalink to &quot;模型应用基础&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>会调用模型 API，只说明程序能够取得一段生成结果；能够稳定使用模型，还要解决输入由谁控制、输出能否解析、结果是否符合业务、失败能否恢复、模型版本是否仍满足任务要求。本分组围绕一次单轮模型调用的完整生命周期，建立从输入到验收的工程边界。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>完成本分组后，你应当能够：</p><ol><li>区分消息角色、指令优先级和不可信内容，识别 Prompt 注入边界。</li><li>把 Prompt 写成包含任务、输入、约束和输出要求的可版本化契约。</li><li>区分 SDK 客户端、请求对象、服务响应、文本便利接口和 Usage。</li><li>用 Schema 约束输出形状，再用业务规则判断结果是否可用。</li><li>把流式响应当作有开始、增量、终止、错误和取消的事件生命周期。</li><li>按失败阶段决定超时、重试、退避和人工处理，而不是无条件重发。</li><li>用代表性样例比较候选模型的质量、延迟、Token 用量与错误类型。</li></ol><h2 id="_2-内容组织" tabindex="-1">2. 内容组织 <a class="header-anchor" href="#_2-内容组织" aria-label="Permalink to &quot;2. 内容组织&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>文章</th><th>核心边界</th></tr></thead><tbody><tr><td>1</td><td><a href="/py-agent/foundations/model-application/messages-instruction-hierarchy">消息与指令层级</a></td><td>谁能下指令，冲突时谁优先</td></tr><tr><td>2</td><td><a href="/py-agent/foundations/model-application/prompt-input-contract">Prompt 输入契约</a></td><td>任务和输入怎样形成可测试契约</td></tr><tr><td>3</td><td><a href="/py-agent/foundations/model-application/model-requests-responses">模型请求与响应</a></td><td>SDK 怎样发送请求并表示返回结果</td></tr><tr><td>4</td><td><a href="/py-agent/foundations/model-application/structured-output-schema">结构化输出与 Schema</a></td><td>模型输出怎样满足机器可解析形状</td></tr><tr><td>5</td><td><a href="/py-agent/foundations/model-application/business-validation-result-handling">业务校验与结果处理</a></td><td>结构正确后怎样判断业务可用</td></tr><tr><td>6</td><td><a href="/py-agent/foundations/model-application/model-streaming">模型流式输出</a></td><td>增量事件怎样聚合、取消和收尾</td></tr><tr><td>7</td><td><a href="/py-agent/foundations/model-application/model-call-reliability">模型调用可靠性</a></td><td>失败怎样分类，哪些请求可以重试</td></tr><tr><td>8</td><td><a href="/py-agent/foundations/model-application/model-selection-basic-evaluation">模型选型与基础评测</a></td><td>怎样用任务数据选择和升级模型</td></tr><tr><td>9</td><td><a href="/py-agent/foundations/model-application/structured-model-application-project">项目：结构化模型应用</a></td><td>怎样把各层整合为可运行、可测试程序</td></tr></tbody></table><p>前两篇定义输入语义，第三篇定义传输边界，第四和第五篇把模型输出逐步提升为业务结果，第六和第七篇处理调用生命周期，最后两篇负责选择与整合。文章之间按责任衔接，不把它们压缩成一套“万能 Prompt 技巧”。</p><h2 id="_3-学习边界" tabindex="-1">3. 学习边界 <a class="header-anchor" href="#_3-学习边界" aria-label="Permalink to &quot;3. 学习边界&quot;">​</a></h2><p>本分组以单轮文本模型应用为主，不展开工具调用、Agent 循环、RAG、多轮长期记忆、模型网关、Web 服务部署和完整可观测性平台。供应商 SDK 会用于观察真实请求与响应，但动态参数和具体事件名称必须以项目锁定版本的官方文档为准。</p><p>Python 类型、Pydantic、pytest、异步任务和 HTTP 客户端已经在前面的分组建立；本分组把它们组合到模型边界，不重复写成 Python 百科。</p>',12)])])}const u=a(i,[["render",n]]);export{m as __pageData,u as default};
